const fs = require("node:fs");
const path = require("node:path");
const crypto = require("node:crypto");
const multer = require("multer");

const uploadDirectory = path.resolve(__dirname, "../uploads");
fs.mkdirSync(uploadDirectory, { recursive: true });

const imageTypes = {
  "image/jpeg": ".jpg",
  "image/png": ".png",
  "image/webp": ".webp"
};

const storage = multer.diskStorage({
  destination: (_req, _file, callback) => callback(null, uploadDirectory),
  filename: (_req, file, callback) => {
    // The filename is generated by the server; the submitted filename is ignored.
    callback(null, `${crypto.randomUUID()}${imageTypes[file.mimetype] || ".upload"}`);
  }
});

const upload = multer({
  storage,
  limits: { fileSize: 5 * 1024 * 1024, files: 1, fields: 10, fieldSize: 10 * 1024 },
  fileFilter: (_req, file, callback) => {
    if (!Object.hasOwn(imageTypes, file.mimetype)) {
      return callback(new multer.MulterError("LIMIT_UNEXPECTED_FILE", "image"));
    }
    return callback(null, true);
  }
});

function uploadImage(req, res, next) {
  upload.single("image")(req, res, (error) => {
    if (!error) return next();
    if (error instanceof multer.MulterError && error.code === "LIMIT_FILE_SIZE") {
      return res.status(413).json({ message: "Image must be 5 MB or smaller" });
    }
    if (error instanceof multer.MulterError && ["LIMIT_FIELD_COUNT", "LIMIT_FIELD_VALUE"].includes(error.code)) {
      return res.status(400).json({ message: "The form contains too many or oversized fields" });
    }
    if (error instanceof multer.MulterError) {
      return res.status(400).json({ message: "Upload one supported image using the 'image' field (JPEG, PNG, or WebP)" });
    }
    return next(error);
  });
}

module.exports = { uploadImage, uploadDirectory };
